import {xml,download,workbook,importFile,wordReport,powerpoint} from './files.js';
import {qrSvg} from './qr.js';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const today=new Date().toISOString().slice(0,10),S={view:'dashboard',lang:localStorage.getItem('hub-language')||'en',project:'all',period:'month',month:today.slice(0,7),year:today.slice(0,4),end:today,start:today.slice(0,7)+'-01',q:'',page:0,data:null,importRows:[],importKind:'employee'};
const words={dashboard:['Overview','نظرة عامة'],projects:['Projects','المشاريع'],employees:['Employee passports','سجلات الموظفين'],training:['Training register','سجل التدريب'],reports:['Report center','مركز التقارير'],workflow:['Monthly workflow','التقارير الشهرية'],automation:['Automation','الأوتوميشن'],access:['Access management','إدارة الصلاحيات'],audit:['Activity log','سجل الأنشطة'],settings:['Settings & source','الإعدادات والسورس'],all:['All projects','كل المشاريع'],welcome:['Corporate training overview','نظرة عامة على تدريب الشركة'],addProject:['Add project','إضافة مشروع'],addEmployee:['Add employee','إضافة موظف'],addTraining:['Record training','تسجيل تدريب'],import:['Import Excel','رفع Excel'],export:['Export report','تصدير تقرير'],refresh:['Refresh','تحديث'],project:['Project','المشروع'],period:['Period','الفترة'],month:['Month','الشهر'],year:['Year','السنة'],save:['Save changes','حفظ التغييرات'],cancel:['Cancel','إلغاء'],search:['Search by name, ID, topic or project…','ابحث بالاسم أو الرقم أو الموضوع أو المشروع…'],noData:['No records yet','لا توجد سجلات بعد'],source:['Download full source','تحميل السورس كامل'],scope:['CORPORATE WORKSPACE','مساحة الشركة'],signout:['Sign out','تسجيل الخروج']};
const t=k=>words[k]?.[S.lang==='ar'?1:0]||k;
const e=xml;
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',building:'M4 21V5l8-3 8 3v16 M8 8h1 M15 8h1 M8 12h1 M15 12h1 M10 21v-5h4v5 M2 21h20',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',book:'M4 3h12l4 4v14H4z M14 3v6h6 M8 13h8 M8 17h5',chart:'M3 3v18h18 M7 16v-5 M12 16V7 M17 16v-8',flow:'M5 3h14v5H5z M5 16h14v5H5z M12 8v8 M9 12l3 3 3-3',bolt:'M13 2 4 14h7l-1 8 10-12h-7z',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z M8 12l3 3 5-6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',gear:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 2h6l1 4 4 1 2 5-3 3v4l-5 3-3-2-4 1-4-5 2-3-1-4 4-2z',plus:'M12 5v14 M5 12h14',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',upload:'M12 16V4 M7 9l5-5 5 5 M4 16v5h16v-5',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 10h18c0-3-3-3-3-10 M10 22h4',arrow:'M5 12h14 M14 7l5 5-5 5',check:'M5 12l4 4L19 6',refresh:'M20 7V3l-4 4 M4 17v4l4-4 M20 7a9 9 0 0 0-16 3 M4 17a9 9 0 0 0 16-3',menu:'M3 6h18 M3 12h18 M3 18h18',file:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8 M8 17h6',qr:'M3 3h6v6H3z M15 3h6v6h-6z M3 15h6v6H3z M15 15h3v3h3v3h-6 M21 12h-9v9 M12 3v9H3',logout:'M9 3H3v18h6 M10 12h11 M16 7l5 5-5 5',mail:'M3 5h18v14H3z M3 5l9 8 9-8',close:'M5 5l14 14 M19 5 5 19'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`;
const number=n=>Number(n||0).toLocaleString(S.lang==='ar'?'ar-EG':'en-US',{maximumFractionDigits:1});
const badge=(status,label=status)=>`<span class="badge ${e(status)}">${e(label)}</span>`;
const roleLabel=r=>({corporate_admin:'Corporate administrator',project_admin:'Project administrator',reviewer:'Reviewer',viewer:'Viewer'}[r]||r);
function toast(text,bad=false){const el=$('#toast');el.textContent=text;el.className='show'+(bad?' error':'');clearTimeout(S.toastTimer);S.toastTimer=setTimeout(()=>el.className='',5000);}
async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw Object.assign(Error(data.error||'Request failed.'),{status:r.status});return data;}
async function load(){S.data=await api('/api/hub');if(S.project!=='all'&&!S.data.projects.some(p=>p.id===S.project))S.project='all';render();}
function visibleProjects(){return S.data.projects.filter(p=>S.project==='all'||p.id===S.project);}
function scoped(kind){return S.data.records.filter(r=>r.kind===kind&&(S.project==='all'||r.projectId===S.project));}
function permitted(p,action='read'){if(S.data.user.corporate)return true;const g=S.data.user.grants.find(g=>g.project===p);return !!g&&(action==='read'||action==='write'&&g.role==='project_admin'||action==='review'&&g.role==='reviewer');}
function canWrite(){return S.data.user.corporate||visibleProjects().some(p=>permitted(p.id,'write'));}
function pName(id){return S.data.projects.find(p=>p.id===id)?.name||id;}
function person(id){return S.data.records.find(r=>r.kind==='employee'&&r.id===id);}
function range(){
 const year=Number(S.year),month=Number(S.month.slice(5,7));
 if(S.period==='all')return ['0000-01-01','9999-12-31'];
 if(S.period==='custom')return[S.start,S.end];
 if(S.period==='week'){const start=new Date(S.end+'T00:00:00Z');start.setUTCDate(start.getUTCDate()-6);return[start.toISOString().slice(0,10),S.end];}
 if(S.period==='year')return[`${year}-01-01`,`${year}-12-31`];
 const count=S.period==='quarter'?3:S.period==='bimonth'?2:1,startMonth=Math.floor((month-1)/count)*count;
 const y=Number(S.month.slice(0,4)),first=new Date(Date.UTC(y,startMonth,1)),last=new Date(Date.UTC(y,startMonth+count,0));return[first.toISOString().slice(0,10),last.toISOString().slice(0,10)];
}
function training(){const[from,to]=range();return scoped('training').filter(r=>r.date>=from&&r.date<=to).sort((a,b)=>b.date.localeCompare(a.date));}
function reportFor(p){return S.data.records.find(r=>r.kind==='report'&&r.projectId===p&&r.month===S.month);}
function totals(rows=training()){return {hours:rows.reduce((n,r)=>n+Number(r.hours),0),attendees:new Set(rows.filter(r=>r.result!=='Failed').map(r=>r.employeeId)).size,records:rows.length,failed:rows.filter(r=>r.result==='Failed').length};}
function empty(title,detail,action='',label=''){return `<div class="empty">${icon('book')}<h3>${e(title)}</h3>${e(detail)}${action?`<br><button class="primary" data-action="${action}">${e(label)}</button>`:''}</div>`;}
function panel(title,sub,body,extra=''){return `<section class="panel"><div class="panel-head"><div><h2>${e(title)}</h2><p class="subtitle">${e(sub)}</p></div>${extra}</div>${body}</section>`;}
function filters(){const years=[...new Set([S.year,...Array.from({length:7},(_,i)=>String(new Date().getFullYear()-i)),...S.data.records.filter(r=>r.date).map(r=>r.date.slice(0,4))])].sort().reverse();return `<div class="filters"><label>${t('project')}<select id="filter-project" aria-label="Project filter"><option value="all">${t('all')}</option>${S.data.projects.map(p=>`<option value="${e(p.id)}" ${p.id===S.project?'selected':''}>${e(p.code)} · ${e(p.name)}</option>`).join('')}</select></label><label>${t('period')}<select id="filter-period" aria-label="Reporting period">${[['week','Weekly'],['month','Monthly'],['bimonth','Bimonthly'],['quarter','Quarterly'],['year','Annual'],['all','All years'],['custom','Custom dates']].map(([id,label])=>`<option value="${id}" ${id===S.period?'selected':''}>${e(label)}</option>`).join('')}</select></label>${['month','bimonth','quarter'].includes(S.period)?`<label>${t('month')}<input id="filter-month" aria-label="Reporting month" type="month" value="${e(S.month)}"></label>`:S.period==='year'?`<label>${t('year')}<select id="filter-year" aria-label="Reporting year">${years.map(y=>`<option ${y===S.year?'selected':''}>${e(y)}</option>`).join('')}</select></label>`:S.period==='week'?`<label>Week ending<input type="date" id="filter-end" value="${e(S.end)}"></label>`:S.period==='custom'?`<label>From<input type="date" id="filter-start" value="${e(S.start)}"></label><label>To<input type="date" id="filter-end" value="${e(S.end)}"></label>`:''}<span class="scope-tag">${S.data.user.corporate?t('scope'):e(roleLabel(S.data.user.grants.find(g=>g.project===S.project)?.role||S.data.user.grants[0]?.role))}</span></div>`;}
function heading(title,sub,buttons=''){return `<div class="page-heading"><div><div class="eyebrow">ORASCOM CONSTRUCTION · LEARNING & DEVELOPMENT</div><h1>${e(title)}</h1><p>${e(sub)}</p></div><div class="heading-actions">${buttons}</div></div>`;}
function btn(action,label,ico='plus',cl='primary',attrs=''){return `<button class="${cl}" data-action="${action}" ${attrs}>${icon(ico)}${e(label)}</button>`;}
function searchBox(){return `<div class="toolbar"><div class="search">${icon('search')}<input id="search" value="${e(S.q)}" placeholder="${e(t('search'))}" aria-label="Search records"></div><span class="badge">${number(S.data.records.length)} accessible records</span></div>`;}
function matches(r){return !S.q||JSON.stringify(r).toLowerCase().includes(S.q.toLowerCase());}
function paginated(rows){const size=25,pages=Math.max(1,Math.ceil(rows.length/size));S.page=Math.min(S.page,pages-1);return {rows:rows.slice(S.page*size,(S.page+1)*size),footer:`<div class="table-foot"><span>${number(rows.length)} records · Page ${S.page+1} of ${pages}</span><span><button class="small ghost" data-page="${S.page-1}" ${S.page===0?'disabled':''}>Previous</button><button class="small ghost" data-page="${S.page+1}" ${S.page===pages-1?'disabled':''}>Next</button></span></div>`};}
function table(headers,rows,footer=''){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>${footer}`;}
function metric(label,value,meta,ico='users'){return `<article class="metric"><span class="metric-icon">${icon(ico)}</span><label>${e(label)}</label><strong>${number(value)}</strong><span class="meta">${e(meta)}</span></article>`;}
function chart(){const rows=training(),buckets=new Map();rows.forEach(r=>{const key=r.date.slice(0,7);buckets.set(key,(buckets.get(key)||0)+Number(r.hours));});if(!rows.length)return `<div class="chart-empty">${icon('chart')}<span>No training hours in the selected period</span></div>`;const values=[...buckets].sort((a,b)=>a[0].localeCompare(b[0])),max=Math.max(1,...values.map(x=>x[1])),width=650,height=220,step=560/values.length,bar=Math.min(32,step*.55);return `<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Training hours by month">${[0,1,2,3,4].map(i=>`<line x1="48" x2="640" y1="${180-i*40}" y2="${180-i*40}"/><text x="8" y="${184-i*40}">${Math.round(max*i/4)}</text>`).join('')}${values.map(([month,v],i)=>`<rect x="${55+i*step+(step-bar)/2}" y="${180-160*v/max}" width="${bar}" height="${160*v/max}" rx="3" fill="#418878"><title>${e(month)}: ${number(v)} hours</title></rect><text text-anchor="middle" x="${55+i*step+step/2}" y="207">${e(month.slice(2))}</text>`).join('')}</svg>`;}
function projectTable(){const rows=training(),ps=visibleProjects();if(!ps.length)return empty('Connect your first project','Add projects individually or import your complete project list.',S.data.user.corporate?'project':'',t('addProject'));return table(['Project','People','Trained','Coverage','Monthly report'],ps.map(p=>{const people=scoped('employee').filter(x=>x.projectId===p.id&&x.active!==false),trained=new Set(rows.filter(t=>t.projectId===p.id&&t.result!=='Failed').map(t=>t.employeeId)).size,pc=people.length?Math.round(trained/people.length*100):0;return `<tr><td><strong>${e(p.name)}</strong><small>${e(p.code)} · ${e(p.country)}</small></td><td>${number(people.length)}</td><td>${number(trained)}</td><td><span class="progress"><i style="width:${Math.min(pc,100)}%"></i></span>${people.length?pc+'%':'—'}</td><td>${badge(reportFor(p.id)?.status||'missing')}</td></tr>`;}));}
function dashboard(){const ts=totals(),ps=visibleProjects(),approved=ps.filter(p=>reportFor(p.id)?.status==='approved').length,pc=ps.length?Math.round(approved/ps.length*100):0,cat=new Map();training().forEach(r=>cat.set(r.category,(cat.get(r.category)||0)+1));const catMax=Math.max(1,...cat.values()),notices=S.data.notifications.filter(n=>!n.resolved&&(S.project==='all'||n.project===S.project));
 return heading(t('welcome'),'A connected view of people, training and project reporting.',btn('export',t('export'),'download','')+(canWrite()?btn('training',t('addTraining')):''))+filters()+`<div class="hero"><div><div class="eyebrow">ONE COMPANY. EVERY PROJECT. A LIFETIME OF LEARNING.</div><h2>${S.lang==='ar'?'التدريب يبدأ في المشروع… وسجلّه يفضل مع الموظف.':'Build capability. Connect every project.'}</h2><p>${S.lang==='ar'?'تابع التدريب والتقارير والاعتمادات من مكان واحد، بسجل دائم لكل موظف وصلاحيات واضحة لكل مشروع.':'One training passport per person. One reporting workflow for every project. Clear ownership from the site to the corporate team.'}</p></div><div class="hero-side"><div><strong>${number(ps.length)}</strong><small>CONNECTED PROJECTS</small></div><div><strong>${pc}%</strong><small>MONTHLY APPROVAL</small></div></div></div><div class="metrics">${metric('Registered employees',scoped('employee').filter(r=>r.active!==false).length,'Active people in the selected scope','users')}${metric('People trained',ts.attendees,'Unique people · excludes failed assessments','shield')}${metric('Training hours',ts.hours,`${number(ts.records)} individual attendance records`,'clock')}${metric('Reports approved',approved,`${S.month} · ${ps.length} expected project reports`,'file')}</div><div class="grid-two">${panel('Training activity','Actual attendance hours · selected period',`<div class="panel-body">${chart()}</div>`,'<div class="legend"><span><i class="dot"></i>Hours</span></div>')}${panel('Monthly submission health',`${S.month} · project report approvals`,`<div class="panel-body ring-wrap"><div class="ring" style="--percent:${pc}%"><strong>${pc}%</strong><small>APPROVED</small></div><div class="ring-legend"><span><i class="dot"></i>Approved<b>${number(approved)} projects</b></span><span><i class="dot gold"></i>Awaiting approval<b>${number(ps.length-approved)} projects</b></span></div></div>`)}</div><div class="grid-two">${panel('Project performance','Coverage uses registered active employees as the denominator.',projectTable(),'<button class="small ghost" data-view="projects">View projects →</button>')}${panel('Training categories','Attendance records by category',`<div class="panel-body">${cat.size?[...cat].sort((a,b)=>b[1]-a[1]).map(([name,n])=>`<div class="category"><div class="category-top"><span>${e(name)}</span><b>${number(n)}</b></div><div class="track"><i style="width:${100*n/catMax}%"></i></div></div>`).join(''):empty('No category data','Categories appear when you add training.')}</div>`)}</div>${panel('Follow-up inbox','Overdue reports and upcoming certificate renewals.',`<div class="panel-body">${notices.length?notices.slice(0,5).map(notice).join(''):empty('All clear','Run the automation check after registering your projects and training.')}</div>`,'<button class="small ghost" data-view="automation">Open automation →</button>')}`;
}
function notice(n){return `<div class="notice"><div class="notice-icon">${icon('bell')}</div><div><p>${e(n.message)}</p><small>${e(n.at.slice(0,16).replace('T',' '))}</small></div>${permitted(n.project,'write')?`<button class="small ghost" data-action="resolve" data-id="${e(n.id)}">Acknowledge</button>`:''}</div>`;}
function projects(){const ps=visibleProjects().filter(matches);return heading(t('projects'),'Manage the complete project portfolio and open each project workspace.',S.data.user.corporate?btn('projectsImport','Import project list','upload','')+btn('project',t('addProject')):'')+filters()+`<div class="project-grid">${ps.map(p=>{const people=S.data.records.filter(r=>r.kind==='employee'&&r.projectId===p.id),tr=training().filter(r=>r.projectId===p.id);return `<article class="panel project-card"><div class="project-top"><div class="project-icon">${icon('building')}</div>${badge('green','Active project')}</div><h3>${e(p.name)}</h3><p>${e(p.code)} / ${e(p.country)} / ${e(p.division)}</p><div class="project-stats"><div><b>${number(people.length)}</b>Employees</div><div><b>${number(totals(tr).hours)}</b>Hours</div><div><b>${number(totals(tr).attendees)}</b>Trained</div></div><div class="project-actions">${badge(reportFor(p.id)?.status||'missing')}<button class="small ghost" data-action="openProject" data-id="${e(p.id)}">Open workspace →</button>${S.data.user.corporate?`<button class="small ghost" data-action="project" data-id="${e(p.id)}">Edit</button>`:''}</div></article>`;}).join('')}</div>${!ps.length?panel('Project portfolio','Every registered project appears here.',empty('Add your project portfolio','Import .xlsx / .csv, or add each project with its code, country and division.',S.data.user.corporate?'project':'',t('addProject'))):''}`;}
function employees(){const rows=scoped('employee').filter(r=>matches({...r,project:pName(r.projectId)})),pg=paginated(rows);return heading(t('employees'),'A permanent employee record, with a QR link and complete training history.',canWrite()?btn('employeeImport',t('import'),'upload','')+btn('employee',t('addEmployee')):'')+filters()+panel('People directory','Employee IDs are unique across the company.',searchBox()+(rows.length?table(['Employee','Employee ID','Role / trade','Company','Project','Status','Passport'],pg.rows.map(r=>`<tr><td><strong>${e(r.name)}</strong></td><td>${e(r.badge)}</td><td>${e(r.trade)}</td><td>${e(r.company)}</td><td>${e(pName(r.projectId))}</td><td>${badge(r.active===false?'draft':'green',r.active===false?'Inactive':'Active')}</td><td><button class="small" data-action="passport" data-id="${e(r.id)}">${icon('qr')}Open passport</button>${permitted(r.projectId,'write')?` <button class="small ghost" data-action="employee" data-id="${e(r.id)}">Edit</button>`:''}</td></tr>`),pg.footer):empty(t('noData'),'Add employees or import your employee list first.')));}
function expiryBadge(r){if(!r.expiry)return '<span class="muted">No expiry</span>';const days=Math.ceil((Date.parse(r.expiry)-Date.parse(today))/86400000);return badge(days<0?'expired':days<=30?'renewal':'green',r.expiry);}
function trainingView(){const rows=training().filter(r=>matches({...r,employee:person(r.employeeId)?.name,badge:person(r.employeeId)?.badge,project:pName(r.projectId)})),pg=paginated(rows);return heading(t('training'),'Record attendance, assessment results, certification dates and evidence.',canWrite()?btn('trainingImport',t('import'),'upload','')+btn('training',t('addTraining')):'')+filters()+panel('Training attendance register','One row per person per course · records are locked after report submission.',searchBox()+(rows.length?table(['Employee','Training topic','Date / hours','Assessment','Certificate','Evidence',''],pg.rows.map(r=>{const pr=person(r.employeeId),files=S.data.evidence.filter(f=>f.record===r.id);return `<tr><td><strong>${e(pr?.name||'Unknown employee')}</strong><small>${e(pr?.badge)} · ${e(pName(r.projectId))}</small></td><td><strong>${e(r.topic)}</strong><small>${e(r.category)} / ${e(r.provider)}</small></td><td>${e(r.date)}<small>${number(r.hours)} hours · ${e(r.method)}</small></td><td>${badge(r.result)}</td><td>${expiryBadge(r)}</td><td><div class="file-links">${files.map(f=>`<a href="/api/evidence/${e(f.id)}" download>${icon('file')}${e(f.name)}</a>`).join('')}</div>${permitted(r.projectId,'write')?`<button class="small ghost" data-action="evidence" data-id="${e(r.id)}">${icon('upload')}Attach</button>`:''}</td><td>${permitted(r.projectId,'write')?`<button class="small ghost" data-action="training" data-id="${e(r.id)}">Edit</button>`:''}</td></tr>`;}),pg.footer):empty(t('noData'),'Record your first course or import training after registering employees.')));}
function reportCards(){const ps=visibleProjects();if(!ps.length)return panel('Monthly reports','Your project list is empty.',empty('Add projects first','Monthly report cards are created from your project portfolio.'));return `<div class="report-list">${ps.map(p=>{const r=reportFor(p.id),write=permitted(p.id,'write'),review=permitted(p.id,'review'),tr=S.data.records.filter(t=>t.kind==='training'&&t.projectId===p.id&&t.date.startsWith(S.month));return `<article class="panel report-card"><div class="report-title"><h3>${e(p.name)}</h3>${badge(r?.status||'missing')}</div><div class="report-detail">${e(p.code)} · ${e(S.month)}<br>${number(tr.length)} attendance records · ${number(tr.reduce((n,t)=>n+Number(t.hours),0))} hours${r?` · Workforce: ${number(r.workforce)}`:''}${r?.notes?`<br>${e(r.notes)}`:''}</div>${r?.history?.length?`<div class="history">${r.history.slice(-2).map(h=>`${e(h.at.slice(0,16).replace('T',' '))} · ${e(h.to)} · ${e(h.by)}${h.comment?`<br>“${e(h.comment)}”`:''}`).join('<br>')}</div>`:''}<div class="report-actions">${write&&(!r||['draft','returned'].includes(r.status))?`<button class="small" data-action="report" data-project="${e(p.id)}" ${r?`data-id="${e(r.id)}"`:''}>${r?'Edit draft':'Prepare report'}</button>`:''}${r&&write&&['draft','returned'].includes(r.status)?`<button class="small primary" data-action="transition" data-id="${e(r.id)}" data-status="submitted">Submit for review</button>`:''}${r?.status==='submitted'&&review?`<button class="small primary" data-action="transition" data-id="${e(r.id)}" data-status="approved">Approve</button><button class="small" data-action="return" data-id="${e(r.id)}">Return with comment</button>`:''}${r?.snapshot?`<button class="small ghost" data-action="snapshot" data-id="${e(r.id)}">Export submitted snapshot</button>`:''}${!write&&!review?'<span class="muted">Read-only project access</span>':''}</div></article>`;}).join('')}</div>`;}
function workflow(){const reports=visibleProjects().map(p=>reportFor(p.id)),stages=[['01','Draft','Project administrator enters training and prepares the monthly return.','draft'],['02','Submit','The report is submitted. Training for this month is locked for review.','submitted'],['03','Review','Reviewer approves or returns the report with a required explanation.','returned'],['04','Approve','The approved report retains its submitted training snapshot.','approved']];return heading(t('workflow'),'A clear owner and a recorded decision at every step.')+filters()+`<div class="filters"><label>Workflow month<input id="workflow-month" type="month" value="${e(S.month)}"></label><span class="muted">Submission and approval statuses always refer to this month.</span></div><div class="flow">${stages.map(([step,title,detail,status])=>`<article class="flow-card"><div class="step">STEP ${step}<strong>${number(reports.filter(r=>r?.status===status).length)}</strong></div><h3>${title}</h3><p>${detail}</p></article>`).join('')}</div>`+reportCards();}
function reports(){const [from,to]=range(),ts=totals();return heading(t('reports'),'Download the selected scope in Excel, Word, PowerPoint or print-ready PDF.')+filters()+`<div class="callout"><strong>${e(S.period==='all'?'All years':from+' → '+to)}</strong> · ${number(training().length)} attendance records · ${number(ts.attendees)} people trained · ${number(ts.hours)} training hours. Exports follow the project and period filters. Workflow status refers to ${e(S.month)}.</div><div class="export-grid">${[['xlsx','Excel workbook','Training register, people, projects and reporting status.','XLSX'],['docx','Word report','Executive summary and a complete training register.','DOCX'],['pptx','PowerPoint deck','Management summary, reporting status and attendance appendix.','PPTX'],['pdf','PDF / print','A formatted landscape report through your browser’s print dialog.','PDF']].map(([a,title,sub,format])=>`<button class="export-card" data-export="${a}">${icon(a==='xlsx'?'chart':'file')}<strong>${title}</strong><small>${sub}</small><span class="filetype">${format}</span></button>`).join('')}</div>${panel('Report completeness','Only recorded information is included in report outputs.',projectTable())}<div class="mt">${panel('Approved submission records',`Monthly workflow status for ${S.month}`,`<div class="panel-body"><p class="subtitle">Open Monthly workflow to prepare, submit, review or return a project report. A submitted snapshot remains separate from subsequent changes.</p><div class="mt">${btn('goWorkflow','Open monthly workflow','flow','')}</div></div>`)}</div>`;}
function automationView(){const ns=S.data.notifications.filter(n=>!n.resolved&&(S.project==='all'||n.project===S.project));return heading(t('automation'),'Recurring checks for reporting deadlines and certificate expiry.',S.data.user.corporate?btn('reminderEmail','Prepare reminder email','mail','')+btn('runAutomation','Run checks now','bolt'):'')+filters()+`<div class="hero"><div><div class="eyebrow">AUTOMATED FOLLOW-UP</div><h2>Daily checks. A single follow-up inbox.</h2><p>${S.data.scheduler.enabled?'The built-in scheduler checks daily at 09:00 Asia/Riyadh while the server is running. Missed runs are picked up when the server resumes.':'The built-in scheduler is disabled by the server administrator.'} Alerts stay inside the hub. Email drafts require manual sending.</p></div><div class="hero-side"><div><strong>${number(ns.length)}</strong><small>OPEN ALERTS</small></div></div></div><div class="callout">Last check: <strong>${S.data.automation?e(S.data.automation.at.replace('T',' ').slice(0,19))+' UTC':'No run recorded yet'}</strong>. Checks are idempotent: the same due item does not create a duplicate alert.</div><div class="rule-list">${visibleProjects().map(p=>{const rule=S.data.records.find(r=>r.kind==='rule'&&r.projectId===p.id);return `<div class="rule-row"><div><h3>${e(p.name)}</h3><p>Previous month’s report due: day ${number(rule?.dueDay||5)} · Certificate warning: ${number(rule?.expiryDays??30)} days before expiry.</p></div><div>${badge(rule?.enabled===false?'draft':'green',rule?.enabled===false?'Paused':'Enabled')}${S.data.user.corporate?` <button class="small ghost" data-action="rule" data-project="${e(p.id)}">Configure</button>`:''}</div></div>`;}).join('')}</div><div class="mt">${panel('Follow-up inbox','Acknowledge an alert after you have reviewed the item.',`<div class="panel-body">${ns.length?ns.map(notice).join(''):empty('No open alerts','Add projects and training, then run checks.')}</div>`)}</div>`;}
function access(){if(!S.data.user.corporate)return empty('Corporate access required','Only corporate administrators can assign access.');return heading(t('access'),'Create accounts by invitation and assign one or several project workspaces.',btn('member','Assign access','shield'))+`<div class="callout"><strong>Your account has access to every registered project.</strong> Project administrators can enter and submit data. Reviewers can approve or return reports. Viewers can read and export. A person can have assignments to multiple projects.</div>`+panel('User access assignments','Invitations are valid for 48 hours. Copy and share each invitation yourself.',S.data.members.length?table(['Person','Project scope','Role','Account',''],S.data.members.map(m=>`<tr><td><strong>${e(m.name||m.email)}</strong><small>${e(m.email)}</small></td><td>${m.project==='*'?'All projects':e(pName(m.project))}</td><td>${badge('green',roleLabel(m.role))}</td><td>${badge(m.name?'green':'draft',m.name?'Active account':'Awaiting activation')}</td><td>${m.email!==S.data.user.email?`<button class="small danger ghost" data-action="revoke" data-email="${e(m.email)}" data-project="${e(m.project)}">Revoke assignment</button>`:'Your account'}</td></tr>`)):empty('No assignments','Assign an email address and project role.'))+`<div class="mt">${panel('Permission model','The server enforces every project boundary.',table(['Role','Project scope','Enter / import','Submit','Approve / return','Assign access'],[['Corporate administrator','All projects','Yes','Yes','Yes','Yes'],['Project administrator','Assigned projects','Yes','Yes','No','No'],['Reviewer','Assigned projects','No','No','Yes','No'],['Viewer','Assigned projects','No','No','No','No']].map(r=>`<tr>${r.map(v=>`<td>${e(v)}</td>`).join('')}</tr>`)))}</div>`;}
function auditView(){const rows=S.data.audit.filter(r=>(S.project==='all'||r.project===S.project)&&matches(r)),pg=paginated(rows);return heading(t('audit'),'A chronological record of changes, workflow decisions and access assignments.')+filters()+panel('Activity history','The latest 1,000 accessible events are shown.',searchBox()+(rows.length?table(['Date / UTC','Actor','Project','Action','Reference'],pg.rows.map(r=>`<tr><td>${e(r.at.replace('T',' ').slice(0,19))}</td><td>${e(r.actor)}</td><td>${r.project==='*'?'Corporate':e(pName(r.project))}</td><td>${e(r.action)}</td><td style="max-width:300px;white-space:normal;overflow-wrap:anywhere">${e(r.target)}</td></tr>`),pg.footer):empty('No activity yet','Changes are recorded automatically.')));}
function settings(){return heading(t('settings'),'Your source code, operating settings and data portability.')+`<div class="settings-grid">${panel('Source code & deployment','The complete application belongs in your own repository.',`<div class="panel-body"><div class="callout">The source package includes the frontend, server, database schema, scheduler, import/export code, tests and deployment guide.</div><a href="/downloads/Training_Hub_Pro_Source.zip" download><button class="primary">${icon('download')}${t('source')}</button></a><p class="subtitle mt">Runs on Node.js 24+ with no package installation. Includes a Dockerfile and documented HTTPS deployment settings.</p></div>`)}${panel('Account & workspace','Your current signed-in identity.',`<div class="panel-body"><ul class="detail-list"><li><span>Name</span><b>${e(S.data.user.name)}</b></li><li><span>Email</span><b>${e(S.data.user.email)}</b></li><li><span>Access</span><b>${S.data.user.corporate?'All projects':'Assigned projects'}</b></li><li><span>Version</span><b>1.0.0 · Portable edition</b></li></ul><div class="mt">${btn('password','Change password','shield','')}</div></div>`)}${panel('Data backup','Keep an independent copy of your project records.',`<div class="panel-body"><p class="modal-intro">Download a JSON data export for migration and review. It excludes password hashes, session tokens and evidence file bytes. Full disaster recovery requires backing up the SQLite database, including attachments, as described in SETUP.md.</p>${S.data.user.corporate?btn('backup','Download data export','download',''):badge('draft','Corporate administrator only')}</div>`)}${panel('Automation runtime','Daily follow-up without republishing the application.',`<div class="panel-body"><ul class="detail-list"><li><span>Scheduler</span><b>${S.data.scheduler.enabled?'Enabled':'Disabled'}</b></li><li><span>Daily check</span><b>09:00 Asia/Riyadh</b></li><li><span>Notifications</span><b>In-app inbox</b></li><li><span>Email sending</span><b>Manual drafts</b></li></ul><p class="subtitle mt">For external scheduling, use the authenticated automation endpoint in the deployment guide. Keep the server and persistent data storage running.</p></div>`)}</div>`;}
function render(){if(!S.data)return;document.documentElement.lang=S.lang;document.documentElement.dir=S.lang==='ar'?'rtl':'ltr';const nav=[['dashboard','grid'],['projects','building'],['employees','users'],['training','book'],['reports','chart'],['workflow','flow'],['automation','bolt'],...(S.data.user.corporate?[['access','shield']]:[]),['audit','clock'],['settings','gear']],unread=S.data.notifications.filter(n=>!n.resolved).length;
 app.innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="/"><span class="brand-symbol">OC</span><div><strong>ORASCOM</strong><small>TRAINING HUB PRO</small></div></a><div class="nav-label">WORKSPACE</div><nav class="nav">${nav.slice(0,4).map(([id,ic])=>`<button data-view="${id}" class="${S.view===id?'active':''}">${icon(ic)}${t(id)}</button>`).join('')}</nav><div class="nav-label">MANAGEMENT</div><nav class="nav">${nav.slice(4).map(([id,ic])=>`<button data-view="${id}" class="${S.view===id?'active':''}">${icon(ic)}${t(id)}${id==='automation'&&unread?`<span class="count">${unread}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><span class="status-dot"></span>CONNECTED TRAINING WORKSPACE<p>People. Projects. Progress.<br>Training Hub Pro · Version 1.0</p></div></aside><div class="workspace"><header class="topbar"><button class="mobile-menu ghost icon-btn" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="crumb">Corporate workspace <span>/</span> <b>${t(S.view)}</b></div><div class="top-actions"><button class="small ghost" data-action="language">${S.lang==='ar'?'English':'العربية'}</button><button class="ghost icon-btn" data-action="refresh" aria-label="Refresh data">${icon('refresh')}</button><button class="ghost icon-btn" data-view="automation" aria-label="Notifications">${icon('bell')}${unread?'<span class="unread"></span>':''}</button><span class="divider"></span><div class="avatar">${e(S.data.user.name.split(/\s/).map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div><div class="identity">${e(S.data.user.name)}<small>${S.data.user.corporate?'Corporate administrator':'Project workspace'}</small></div><button class="ghost icon-btn" data-action="logout" aria-label="Sign out">${icon('logout')}</button></div></header><main class="main">${({dashboard,projects,employees,training:trainingView,reports,workflow,automation:automationView,access,audit:auditView,settings}[S.view]||dashboard)()}<footer class="footer"><span>© ${new Date().getFullYear()} Orascom Construction · Training Hub Pro</span><span><i class="status-dot"></i>Shared project database · ${new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</span></footer></main></div></div>`;
}
function field(label,name,value='',type='text',full=false,options=null,help=''){return `<div class="field ${full?'full':''}"><label for="f-${name}">${e(label)}</label>${options?`<select id="f-${name}" name="${name}" required>${options.map(([id,l])=>`<option value="${e(id)}" ${String(id)===String(value)?'selected':''}>${e(l)}</option>`).join('')}</select>`:type==='textarea'?`<textarea id="f-${name}" name="${name}">${e(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${['notes','expiry'].includes(name)?'':'required'} ${type==='password'?'minlength="12" maxlength="256" autocomplete="new-password"':''} ${type==='number'?'min="0" step="any"':''}>`}${help?`<small>${e(help)}</small>`:''}</div>`;}
function projectField(value='',write=true){const ps=S.data.projects.filter(p=>!write||permitted(p.id,'write'));return field('Project','projectId',value||S.project!=='all'&&S.project||ps[0]?.id,'',true,ps.length?ps.map(p=>[p.id,`${p.code} · ${p.name}`]):[['','Add a project first']]);}
function showModal(title,body){modal.innerHTML=`<div class="modal-head"><h2>${e(title)}</h2><button class="ghost" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
function form(title,type,fields,extra='',id='',project=''){S.form={type,id,project};showModal(title,`${extra}<form id="edit-form" class="form-grid">${fields}<div class="form-error"></div><div class="form-actions"><button type="button" data-action="close">${t('cancel')}</button><button class="primary" type="submit">${t('save')}</button></div></form>`);}
function editor(type,id='',proj=''){
 const r=id?S.data.records.find(x=>x.id===id)||S.data.projects.find(x=>x.id===id):{};
 if(type==='project')return form(id?'Edit project':'Add a project',type,field('Project code','code',r.code)+field('Project name','name',r.name)+field('Country','country',r.country)+field('Division','division',r.division),'',id);
 if(type==='employee')return form(id?'Edit employee':'Employee registration',type,projectField(r.projectId)+field('Full name','name',r.name)+field('Employee ID / badge','badge',r.badge)+field('Trade / role','trade',r.trade)+field('Company / contractor','company',r.company)+field('Status','active',r.active===false?'false':'true','',true,[['true','Active'],['false','Inactive']]),'<p class="modal-intro">Employee IDs are unique across the company. The passport link requires sign-in and project access.</p>',id);
 if(type==='training'){
  const project=r.projectId||S.project!=='all'&&S.project||S.data.projects.find(p=>permitted(p.id,'write'))?.id,people=S.data.records.filter(x=>x.kind==='employee'&&x.projectId===project&&x.active!==false);
  return form(id?'Edit training attendance':'Record training attendance',type,projectField(project)+field('Employee','employeeId',r.employeeId,'',true,people.length?people.map(p=>[p.id,`${p.name} · ${p.badge}`]):[['','Register employees in this project first']])+field('Training topic','topic',r.topic)+field('Category','category',r.category||'HSE Training')+field('Training provider','provider',r.provider||'Internal')+field('Training date','date',r.date||today,'date')+field('Training hours','hours',r.hours||1,'number')+field('Method','method',r.method||'Classroom','',false,[['Classroom','Classroom'],['Practical','Practical'],['Online','Online'],['On the job','On the job']])+field('Assessment result','result',r.result||'Passed','',false,[['Passed','Passed'],['Attended','Attended'],['Failed','Failed']])+field('Certificate expiry (optional)','expiry',r.expiry,'date'),'<p class="modal-intro">One person per attendance record. Add the certificate or evidence after saving.</p>',id);
 }
 if(type==='report')return form('Prepare monthly report',type,field('Reporting month','month',r.month||S.month,'month')+field('Project workforce','workforce',r.workforce??0,'number')+field('Notes / nil-return explanation','notes',r.notes,'textarea',true),'<p class="modal-intro">Training totals come from the project register. Submission saves a snapshot and locks this month’s training.</p>',id,proj||r.projectId);
 if(type==='member')return form('Assign project access',type,field('Email address','email','','email',true)+field('Role','role','project_admin','',true,[['project_admin','Project administrator'],['reviewer','Reviewer'],['viewer','Viewer'],['corporate_admin','Corporate administrator · all projects']])+projectField('',false),'<p class="modal-intro">New users receive an activation link for you to copy and share. Existing users receive the assignment immediately. No email is sent automatically.</p>');
 if(type==='rule'){const rule=S.data.records.find(r=>r.kind==='rule'&&r.projectId===proj)||{};return form(`Automation · ${pName(proj)}`,type,field('Monthly due day (1–28)','dueDay',rule.dueDay||5,'number')+field('Certificate warning days (1–365)','expiryDays',rule.expiryDays??30,'number')+field('Rule status','enabled',rule.enabled===false?'false':'true','',true,[['true','Enabled'],['false','Paused']]),'<p class="modal-intro">The previous month’s report is due on this day of the following month. Certificate alerts include expired and soon-to-expire records.</p>','',proj);}
 if(type==='return')return form('Return report for correction',type,field('Required correction comment','comment','','textarea',true),'',id);
 if(type==='password')return form('Change your password',type,field('Current password','current','','password',true)+field('New password (12+ characters)','password','','password',true));
}
function passport(id){const p=person(id);if(!p)return;const rows=S.data.records.filter(t=>t.kind==='training'&&t.employeeId===id).sort((a,b)=>b.date.localeCompare(a.date)),url=location.origin+'/p/'+id;let qr='';try{qr=qrSvg(url);}catch(err){qr=`<p>${e(err.message)}</p>`;}
 showModal('Employee training passport',`<div class="passport-head"><div><div class="eyebrow">ORASCOM CONSTRUCTION · TRAINING PASSPORT</div><h3>${e(p.name)}</h3><p>Employee ID: ${e(p.badge)}<br>${e(p.trade)} · ${e(p.company)}<br>${e(pName(p.projectId))}</p></div><div class="qr">${qr}</div></div><div class="metrics">${metric('Training records',rows.length,'Complete history','book')}${metric('Training hours',totals(rows).hours,'Recorded attendance','clock')}</div>${rows.length?table(['Course','Date','Result','Expiry'],rows.map(r=>`<tr><td><strong>${e(r.topic)}</strong><small>${e(r.provider)}</small></td><td>${e(r.date)}</td><td>${badge(r.result)}</td><td>${expiryBadge(r)}</td></tr>`)):empty('No training recorded','Attendance records appear here automatically.')}<div class="passport-link">QR links to this protected passport: <a href="${e(url)}">${e(url)}</a></div><div class="form-actions">${btn('passportPrint','Print passport','file','',`data-id="${e(id)}"`)}${btn('qrDownload','Download QR','download','primary',`data-id="${e(id)}"`)}</div>`);
}
const templates={employee:{headers:['name','badge','trade','company'],rows:[]},training:{headers:['badge','topic','category','provider','date','hours','method','result','expiry'],rows:[]},projects:{headers:['code','name','country','division'],rows:[]}};
function importModal(kind){S.importKind=kind;S.importRows=[];S.form=null;showModal(`Import ${kind==='employee'?'employees':kind==='training'?'training records':'project list'}`,`<p class="modal-intro">Download the template and keep its column headers. Upload .xlsx or .csv, up to 1,000 rows. Dates must use YYYY-MM-DD. Import employees before training. Existing employee IDs and duplicate training records are rejected.</p>${kind!=='projects'?projectField():''}<button class="small" data-action="template">${icon('download')}Download blank XLSX template</button><div class="dropzone">${icon('upload')}<p>Select your completed workbook</p><input id="import-file" type="file" accept=".xlsx,.csv" aria-label="Select Excel or CSV import"></div><div id="import-status" class="modal-intro"></div><div id="import-preview"></div><div class="form-actions"><button data-action="close">Cancel</button><button class="primary" data-action="commitImport" disabled id="import-commit">Validate & import all rows</button></div>`);}
function exportData(snapshot=null){
 const rows=snapshot?snapshot.snapshot||[]:training(),people=snapshot?rows.map(t=>t.employee).filter(Boolean):scoped('employee'),ps=snapshot?S.data.projects.filter(p=>p.id===snapshot.projectId):visibleProjects();
 const headers=['Employee','Employee ID','Project','Category','Training Provider','Training Topic','Date','Hours','Method','Assessment','Expiry'];
 const detail=rows.map(r=>{const pr=snapshot?r.employee:person(r.employeeId);return[pr?.name||'',pr?.badge||'',pName(r.projectId),r.category,r.provider,r.topic,r.date,Number(r.hours),r.method,r.result,r.expiry||''];});
 const reportRows=ps.map(p=>{const r=snapshot||reportFor(p.id);return[p.name,p.code,r?.month||S.month,r?.status||'missing',r?.workforce||0];});
 const [from,to]=range(),title='Corporate Training Report',subtitle=`${snapshot?'Submitted snapshot · '+snapshot.month:from+' to '+to} | ${snapshot?pName(snapshot.projectId):S.project==='all'?'All projects':pName(S.project)} | Generated ${today}`,ts=totals(rows);
 return{rows,people,ps,headers,detail,reportRows,title,subtitle,ts,summary:[`Scope: ${subtitle}`,`Attendance records: ${rows.length} | People trained: ${ts.attendees} | Hours: ${ts.hours}`,`Assessment results: ${ts.failed} failed; ${rows.length-ts.failed} passed / attended.`,snapshot?`Report status: ${snapshot.status}. Submitted training snapshot retained.`:`Workflow statuses refer to ${S.month}. Activity exports include recorded training regardless of report approval.`]};
}
function doExport(format,snapshot=null){
 const d=exportData(snapshot),stem=`Training_Report_${snapshot?snapshot.month:S.period==='all'?'All_Years':range().join('_')}`;
 if(format==='xlsx')download(workbook([{name:'Training Register',headers:d.headers,rows:d.detail},{name:'Employees',headers:['Employee','Employee ID','Trade','Company','Project'],rows:d.people.map(p=>[p.name,p.badge,p.trade,p.company,pName(p.projectId||snapshot?.projectId)])},{name:'Report Status',headers:['Project','Code','Month','Status','Workforce'],rows:d.reportRows},{name:'Projects',headers:['Project','Code','Country','Division'],rows:d.ps.map(p=>[p.name,p.code,p.country,p.division])}]),stem+'.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
 else if(format==='docx')download(wordReport(d.title,d.subtitle,d.summary,d.headers,d.detail),stem+'.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document');
 else if(format==='pptx')download(powerpoint(d.title,d.subtitle,[['Attendance records',d.rows.length],['People trained',d.ts.attendees],['Training hours',d.ts.hours],['Projects in scope',d.ps.length]],d.reportRows.map(r=>[r[0],r[2],r[3]]),d.detail.map(r=>[r[0],r[5],r[6],r[9]])),stem+'.pptx','application/vnd.openxmlformats-officedocument.presentationml.presentation');
 else printReport(d.title,d.subtitle,d.summary,d.headers,d.detail);
 toast(format==='pdf'?'Choose Save as PDF in the print dialog.':'Report downloaded.');
}
function printReport(title,sub,summary,headers,rows,extra=''){let old=$('.print-report');if(old)old.remove();const div=document.createElement('div');div.className='print-report';div.innerHTML=`<p>ORASCOM CONSTRUCTION · TRAINING HUB PRO</p><h1>${e(title)}</h1><p>${e(sub)}</p>${summary.map(s=>`<p>${e(s)}</p>`).join('')}${extra}<table><thead><tr>${headers.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${e(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;document.body.append(div);window.print();}
async function reminderEmail(){const ns=S.data.notifications.filter(n=>!n.resolved&&(S.project==='all'||n.project===S.project)),emails=[...new Set(S.data.members.filter(m=>m.role==='project_admin'&&(S.project==='all'||m.project===S.project)).map(m=>m.email))];const body=`Dear Project Training Teams,\r\n\r\nPlease review and address the following outstanding training reporting and certification items:\r\n\r\n${ns.length?ns.map((n,i)=>`${i+1}. ${n.message}`).join('\r\n'):'No outstanding alerts are currently recorded.'}\r\n\r\nPlease update the Training Hub, attach the supporting evidence where applicable, and submit your monthly report for review.\r\n\r\nBest regards,\r\n${S.data.user.name}`;download(`To: ${emails.join(', ')}\r\nSubject: Training Hub - Outstanding Reports and Certificate Renewals\r\nMIME-Version: 1.0\r\nContent-Type: text/plain; charset=UTF-8\r\n\r\n${body}`,'Training_Follow_Up.eml','message/rfc822');toast('Consolidated email draft downloaded. Review recipients before sending.');}
async function handleAction(action,el){
 const id=el?.dataset.id||'',project=el?.dataset.project||'';
 if(action==='close'){modal.close();return;}
 if(action==='language'){S.lang=S.lang==='en'?'ar':'en';localStorage.setItem('hub-language',S.lang);if(S.data)render();else boot();return;}
 if(action==='menu'){$('.sidebar')?.classList.toggle('open');return;}
 if(action==='logout'){await api('/api/logout',{});S.data=null;await boot();return;}
 if(action==='refresh'){await load();toast('Data refreshed.');return;}
 if(['project','employee','training','report','member','rule','return','password'].includes(action)){editor(action,id,project);return;}
 if(action==='openProject'){S.project=id;S.view='dashboard';S.q='';S.page=0;render();return;}
 if(action==='export'){S.view='reports';render();return;}
 if(action==='goWorkflow'){S.view='workflow';render();return;}
 if(action==='passport'){passport(id);return;}
 if(action==='qrDownload'){download(qrSvg(location.origin+'/p/'+id),`Training_Passport_${person(id).badge}.svg`,'image/svg+xml');return;}
 if(action==='passportPrint'){const p=person(id),rows=S.data.records.filter(r=>r.kind==='training'&&r.employeeId===id);modal.close();printReport(p.name,`${p.badge} · ${p.trade} · ${p.company}`,['Project: '+pName(p.projectId),'QR links require sign-in and project access.'],['Course','Date','Hours','Assessment','Expiry'],rows.map(r=>[r.topic,r.date,r.hours,r.result,r.expiry]),`<div style="width:110px">${qrSvg(location.origin+'/p/'+id)}</div>`);return;}
 if(action==='snapshot'){doExport('xlsx',S.data.records.find(r=>r.id===id));return;}
 if(['employeeImport','trainingImport','projectsImport'].includes(action)){importModal(action==='projectsImport'?'projects':action==='employeeImport'?'employee':'training');return;}
 if(action==='template'){const temp=templates[S.importKind];download(workbook([{name:'Import Template',...temp}]),`${S.importKind}_import_template.xlsx`,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');return;}
 if(action==='commitImport'){
  const p=$('#f-projectId')?.value;if(S.importKind!=='projects'&&!p)throw Error('Choose a project.');const b=S.importKind==='projects'?{action:'projectsImport',rows:S.importRows}:{action:'import',kind:S.importKind,projectId:p,rows:S.importRows};el.disabled=true;try{const r=await api('/api/hub',b);modal.close();await load();toast(`${r.count} records imported.`);}catch(err){el.disabled=false;throw err;}return;
 }
 if(action==='transition'){await api('/api/hub',{action:'transition',id,status:el.dataset.status});await load();toast('Workflow updated.');return;}
 if(action==='revoke'){showModal('Revoke project assignment',`<p class="modal-intro">Remove ${e(el.dataset.email)} from ${e(project==='*'?'corporate access':pName(project))}? Existing sessions and pending invitations will be invalidated. You can assign access again later.</p><div class="form-actions"><button data-action="close">Cancel</button><button class="danger" data-action="confirmRevoke" data-email="${e(el.dataset.email)}" data-project="${e(project)}">Revoke assignment</button></div>`);return;}
 if(action==='confirmRevoke'){await api('/api/hub',{action:'revoke',data:{email:el.dataset.email,projectId:project}});modal.close();await load();toast('Assignment revoked.');return;}
 if(action==='resolve'){await api('/api/hub',{action:'resolve',id});await load();toast('Alert acknowledged.');return;}
 if(action==='runAutomation'){el.disabled=true;try{const r=await api('/api/hub',{action:'runAutomation'});await load();toast(`${r.checkedProjects} projects checked. ${r.created} new alerts.`);}finally{el.disabled=false;}return;}
 if(action==='reminderEmail'){await reminderEmail();return;}
 if(action==='backup'){download(JSON.stringify(await api('/api/backup'),null,2),`Training_Hub_Data_Export_${today}.json`,'application/json');return;}
 if(action==='evidence'){S.evidenceRecord=id;showModal('Attach training evidence',`<p class="modal-intro">Upload a PDF, PNG or JPEG, up to 7 MB. This file is accessible only to users assigned to the same project.</p><input id="evidence-file" type="file" accept="application/pdf,image/png,image/jpeg" aria-label="Choose training evidence"><div id="evidence-status" class="modal-intro mt"></div>`);return;}
}
document.addEventListener('click',async ev=>{
 const b=ev.target.closest('[data-view],[data-action],[data-export],[data-page]');if(!b)return;
 try{if(b.dataset.view){S.view=b.dataset.view;S.q='';S.page=0;render();window.scrollTo(0,0);}else if(b.dataset.export)doExport(b.dataset.export);else if(b.dataset.page!==undefined){S.page=Number(b.dataset.page);render();}else await handleAction(b.dataset.action,b);}catch(err){toast(err.message,true);}
});
document.addEventListener('input',ev=>{if(ev.target.id==='search'){const pos=ev.target.selectionStart;S.q=ev.target.value;S.page=0;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
document.addEventListener('change',async ev=>{
 const el=ev.target;try{
  const filterMap={'filter-project':'project','filter-period':'period','filter-month':'month','workflow-month':'month','filter-year':'year','filter-start':'start','filter-end':'end'};
  if(filterMap[el.id]){if(!el.value)return;S[filterMap[el.id]]=el.value;if(S.period==='custom'&&S.start>S.end){toast('Start date must be before end date.',true);return;}S.page=0;render();return;}
  if(el.id==='f-projectId'&&S.form?.type==='training'){
   const people=S.data.records.filter(r=>r.kind==='employee'&&r.projectId===el.value&&r.active!==false),field=$('#f-employeeId');field.innerHTML=people.length?people.map(p=>`<option value="${e(p.id)}">${e(p.name)} · ${e(p.badge)}</option>`).join(''):'<option value="">Register employees in this project first</option>';return;
  }
  if(el.id==='f-role'&&S.form?.type==='member'){$('#f-projectId').disabled=el.value==='corporate_admin';return;}
  if(el.id==='import-file'){
   const file=el.files[0];if(!file)return;$('#import-status').textContent='Reading workbook…';$('#import-commit').disabled=true;
   try{const rows=await importFile(file);if(rows.length>1000)throw Error('Split the file into batches of 1,000 rows.');const requiredHeaders=templates[S.importKind].headers.filter(h=>h!=='expiry');for(const h of requiredHeaders)if(!Object.hasOwn(rows[0],h))throw Error(`Missing column: ${h}. Use the supplied template.`);S.importRows=rows;$('#import-status').textContent=`${rows.length} rows ready for server validation. Preview of first 10 rows:`;$('#import-preview').innerHTML=`<div class="import-preview">${table(Object.keys(rows[0]),rows.slice(0,10).map(r=>`<tr>${Object.values(r).map(v=>`<td>${e(v)}</td>`).join('')}</tr>`))}</div>`;$('#import-commit').disabled=false;}catch(err){S.importRows=[];$('#import-status').textContent=err.message;}return;
  }
  if(el.id==='evidence-file'){
   const file=el.files[0];if(!file)return;if(file.size>7*1024*1024)throw Error('Evidence limit is 7 MB.');$('#evidence-status').textContent='Uploading evidence…';const bytes=new Uint8Array(await file.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.slice(i,i+8192));await api('/api/evidence',{record:S.evidenceRecord,name:file.name,type:file.type,base64:btoa(raw)});modal.close();await load();toast('Evidence attached.');
  }
 }catch(err){toast(err.message,true);if($('#evidence-status'))$('#evidence-status').textContent=err.message;}
});
document.addEventListener('submit',async ev=>{
 ev.preventDefault();const f=ev.target,button=f.querySelector('[type=submit]'),err=f.querySelector('.form-error'),values=Object.fromEntries(new FormData(f));button.disabled=true;if(err)err.classList.remove('show');
 try{
  if(f.id==='auth-form'){
   const endpoint=S.authMode==='setup'?'/api/setup':S.authMode==='activate'?'/api/activate':'/api/login';await api(endpoint,{...values,token:new URLSearchParams(location.search).get('invite')});if(S.authMode==='activate')history.replaceState(null,'','/');await load();openLinkedPassport();return;
  }
  if(f.id==='edit-form'){
   const {type,id,project}=S.form;let result;
   if(type==='password')result=await api('/api/password',values);
   else if(type==='return')result=await api('/api/hub',{action:'transition',id,status:'returned',comment:values.comment});
   else if(type==='project')result=await api('/api/hub',{action:'project',id,data:values});
   else if(type==='member')result=await api('/api/hub',{action:'member',data:values});
   else if(type==='rule')result=await api('/api/hub',{action:'rule',projectId:project,data:{...values,enabled:values.enabled==='true'}});
   else result=await api('/api/hub',{action:'save',kind:type,id,projectId:project||values.projectId,data:{...values,active:values.active!=='false'}});
   modal.close();await load();toast('Saved successfully.');
   if(result.invite)showModal('Invitation ready to share',`<p class="modal-intro">Send this one-time link to ${e(values.email)}. It expires in 48 hours. The person will choose their own password. No message has been sent.</p><div class="field"><label for="invite-link">Activation link</label><input id="invite-link" value="${e(result.invite)}" readonly></div><div class="form-actions"><button class="primary" data-action="close">Done</button></div>`);
  }
 }catch(error){if(err){err.textContent=error.message;err.classList.add('show');}else toast(error.message,true);}finally{button.disabled=false;}
});
function authScreen(session){const invite=new URLSearchParams(location.search).get('invite');S.authMode=invite?'activate':session.setup?'setup':'login';document.documentElement.dir=S.lang==='ar'?'rtl':'ltr';document.documentElement.lang=S.lang;const mode=S.authMode;
 app.innerHTML=`<div class="auth-page"><section class="auth-story"><div class="brand"><span class="brand-symbol">OC</span><div><strong>ORASCOM</strong><small>TRAINING HUB PRO</small></div></div><div class="eyebrow" style="color:#d7b482">CONNECTED LEARNING. COMPANY-WIDE.</div><h1>One company.<br>Every project.<br><em>A lifetime of learning.</em></h1><p>Connect your project training teams with a permanent record of each person’s development, a clear approval workflow and one corporate view.</p><div class="auth-features"><span>${icon('qr')}Employee passports</span><span>${icon('shield')}Project access</span><span>${icon('bolt')}Automated follow-up</span></div></section><section class="auth-form"><div class="eyebrow">ORASCOM CONSTRUCTION</div><h2>${mode==='setup'?'Create your corporate workspace':mode==='activate'?'Activate your account':S.lang==='ar'?'أهلًا بيك في مركز التدريب':'Welcome to Training Hub'}</h2><p>${mode==='setup'?'Set up the first corporate administrator. This account will have access to every project you register.':mode==='activate'?'Choose your display name and password to accept the project access assignment.':S.lang==='ar'?'ادخل بحسابك. كل مسؤول مشروع يفتح بيانات المشاريع المخصصة له فقط.':'Sign in to your workspace. Your assigned role controls project access.'}</p><form id="auth-form" class="form-grid">${mode!=='login'?field('Your name','name','','text',true):''}${mode!=='activate'?field('Email address','email','','email',true):''}${field(mode==='login'?'Password':'Password · at least 12 characters','password','','password',true)}${mode==='setup'&&!session.setupAllowed?field('Initial setup token','setupToken','','password',true):''}<div class="form-error"></div><button class="primary" type="submit">${mode==='setup'?'Create administrator account':mode==='activate'?'Activate & open workspace':S.lang==='ar'?'دخول':'Sign in'}${icon('arrow')}</button></form><div class="auth-note">Training Hub Pro · Version 1.0<br>Corporate administrators see all registered projects. Project users see their assigned workspaces.</div><div class="mt"><button class="small ghost" data-action="language">${S.lang==='ar'?'English':'العربية'}</button><a class="text-link" href="/downloads/Training_Hub_Pro_Source.zip" download>Download source</a></div></section></div>`;
 if(mode==='login')$('#f-password').setAttribute('minlength','1');if(mode==='login')$('#f-password').setAttribute('autocomplete','current-password');
}
function openLinkedPassport(){const id=location.pathname.startsWith('/p/')?location.pathname.split('/').pop():null;if(id){S.view='employees';render();if(person(id))passport(id);else toast('Passport not found or outside your assigned projects.',true);}}
async function boot(){try{const session=await api('/api/session');if(session.user){await load();openLinkedPassport();}else authScreen(session);}catch(err){app.innerHTML=`<div class="error-screen"><div class="brand-symbol" style="margin:auto">OC</div><h2>Training Hub is unavailable</h2><p>${e(err.message)}</p><p>Start the application with Node.js 24 and keep the server running.</p><button data-action="language">Retry</button></div>`;}}
boot();
